# -*- coding: utf-8 -*-
"""Generate an offline/shareable QA screen from the verified local matrices.
No Backend access, credentials, database changes or production entry.
"""
from pathlib import Path
import datetime
import json
import re

ROOT = Path(__file__).resolve().parents[2]
inventory = (ROOT / 'OCV_BOOKING_ENDPOINT_INVENTORY.md').read_text(encoding='utf-8')
coverage = (ROOT / 'OCV_BOOKING_API_COVERAGE.md').read_text(encoding='utf-8')
classes = {}
for line in inventory.splitlines():
    cells = [value.strip() for value in line.strip('|').split('|')]
    if line.startswith('| ') and len(cells) == 6 and re.match(r'^(GET|POST|PUT|PATCH|DELETE) /', cells[0]):
        classes[cells[0]] = cells[1]
rows = []
for line in coverage.splitlines():
    cells = [value.strip() for value in line.strip('|').split('|')]
    if line.startswith('| ') and len(cells) == 7 and re.match(r'^(GET|POST|PUT|PATCH|DELETE) /', cells[1]):
        workflow, endpoint, dto, permission, screen, proof, status = cells
        method, path = endpoint.split(' ', 1)
        rows.append(dict(key=endpoint, method=method, path=path, workflow=workflow,
                         dto=dto.replace('&lt;', '<').replace('&gt;', '>'), permission=permission,
                         screen=screen, proof=proof, status=status, category=classes[endpoint],
                         wired=status.startswith('WIRED')))
assert len(rows) == 58 and sum(row['wired'] for row in rows) == 41
assert {kind:sum(row['category']==kind for row in rows) for kind in classes.values() if kind != 'OUT_OF_SCOPE'} == {'REQUIRED_CUSTOMER':34,'REQUIRED_SUPPORTING':21,'REQUIRED_STAFF_BOOKING':3}

